local config = {
  ui_story_31720401_1_dialog_content = "<color=#e8d9bb>Tok, tok!</color>",
  ui_story_31720401_2_dialog_content = "Siapa di sana?",
  ui_story_31720401_3_dialog_content = "Ibu, Ayah, ini aku, Lilica!",
  ui_story_31720401_4_dialog_content = "<color=#e8d9bb>Kriek—</color>",
  ui_story_31720401_5_dialog_content = "Lilika? Ini benar-benar Lilica kami!",
