  ui_story_31720401_10_dialog_content = "Aku tahu kamu!",
  ui_story_31720401_11_dialog_content = "(Wow, cerita tentang saya bahkan sampai ke kota terpencil seperti ini?)",
  ui_story_31720401_12_dialog_content = "(Dalam hal ini, saya akan memperkenalkan diri dengan benar.)",
  ui_story_31720401_13_dialog_content = "Heh, ya, aku memang Caele—",
