  ui_story_31720401_18_dialog_content = "Mereka membuat berita sensasional dan mengada-ada hanya untuk diedarkan! Anda harus mengambil semuanya dengan sebutir garam!",
  ui_story_31720401_19_dialog_content = "Begitukah... Siapa itu PlayerName, kemudian?",
  ui_story_31720401_20_dialog_content = "PlayerName adalah PlayerName, seseorang yang sangat penting bagi saya!",
