  ui_story_31720401_22_dialog_content = "Oh?!",
  ui_story_31720401_23_dialog_content = "(Um... Orang tua Lilica menatapku lebih curiga setelah apa yang dia katakan.)",
  ui_story_31720401_24_dialog_content = "Ahem. Itu sedikit berlebihan. Aku sebenarnya hanya milik Lilica...",
