  ui_story_31720401_28_option_content = "teman",
  ui_story_31720401_29_dialog_content = "Teman-teman, atau sesuatu yang lebih?",
  ui_story_31720401_30_dialog_content = "Mama, PlayerName terkenal di seluruh Astra.",
  ui_story_31720401_31_dialog_content = "Saya cukup beruntung hanya untuk menjadi teman-teman! Apalagi-",
  ui_story_31720401_32_dialog_content = "PlayerName akan menjadi investor untuk film saya berikutnya!",
  ui_story_31720401_33_dialog_content = "(Tunggu, apa? Aku hanya berjanji untuk mengantarnya pulang!)",
  ui_story_31720401_34_dialog_content = "Sungguh?",
  ui_story_31720401_35_dialog_content = "Ya!",
  ui_story_31720401_36_dialog_content = "PlayerName mengantar saya pulang untuk membantu saya menemukan inspirasi untuk sebuah film.",
  ui_story_31720401_37_dialog_content = "Oh, kurasa aku langsung mengambil kesimpulan, ahahaha... Kesalahpahaman, itu saja.",
