  ui_story_31720401_40_dialog_content = "Tidak apa-apa, Anda tidak perlu meminta maaf!",
  ui_story_31720401_41_dialog_content = "<color=#e8d9bb>*Statis* *Statis*</color>",
  ui_story_31720401_42_dialog_content = "Hah? Apakah itu suara...",
  ui_story_31720401_43_dialog_content = "Sebuah proyektor?!",
  ui_story_31720401_44_dialog_content = "Bukankah saya mengatakan saya akan membelikan Anda model mewah setelah saya mulai menghasilkan banyak uang?",
  ui_story_31720401_45_dialog_content = "Yah, ayahmu punya banyak waktu luang dan membuat sendiri dari suku cadang daur ulang.",
  ui_story_31720401_46_dialog_content = "Anda bekerja keras untuk uang Anda, Lilica, jadi Anda harus menyimpannya untuk diri sendiri.",
  ui_story_31720401_47_dialog_content = "Beli sendiri gaun dan aksesoris yang lebih cantik, oke?",
  ui_story_31720401_48_dialog_content = "Baiklah…",
  ui_story_31720401_49_dialog_content = "<color=#e8d9bb>\"Halo, semuanya! *statis*...\"</color>",
  ui_story_31720401_50_dialog_content = "Apa yang sedang diputar sekarang?",
  ui_story_31720401_51_dialog_content = "Ah, jangan katakan padaku...",
  ui_story_31720401_52_dialog_content = "Tidak, PlayerName, jangan lihat!",
  ui_story_31720401_53_dialog_content = "\"Apakah itu merekam, Ayah?\"",
  ui_story_31720401_54_dialog_content = "\"Biar kuperiksa... Uh, ingat untuk melepas penutup lensa lain kali, Lilica.\"",
  ui_story_31720401_55_dialog_content = "\"Oke, mengerti! Ahem, hari ini aku merekam hari bahagia dalam hidup Lilica!\"",
  ui_story_31720401_56_dialog_content = "\"Lihat kameranya, Ayah.\"",
  ui_story_31720401_57_dialog_content = "\"Pria ini adalah ayahku yang sangat hebat.\"",
  ui_story_31720401_58_dialog_content = "\"Dia memberiku kamera ini!\"",
  ui_story_31720401_59_dialog_content = "\"Ahem... Halo semuanya! Haha, hai!\"",
  ui_story_31720401_60_dialog_content = "\"Tunggu, aku ingin berada di film juga!\"",
  ui_story_31720401_61_dialog_content = "<color=#e8d9bb>*Statis*</color>",
  ui_story_31720401_62_dialog_content = "Hei, kenapa kau memotongnya?",
  ui_story_31720401_63_dialog_content = "Aha... hahaha... Saat itu aku masih kecil dan tidak tahu apa-apa.",
  ui_story_31720401_64_dialog_content = "Jika ada yang melihatnya, itu akan merusak citraku... Jadi ya, um, anggap saja kita tidak pernah melihatnya.",
  ui_story_31720401_65_dialog_content = "Oke, tapi menurutku...",
  ui_story_31720401_66_dialog_content = "Ini lucu.",
  ui_story_31720401_67_dialog_content = "Saya ingin melihat lebih banyak seperti apa Anda sebagai seorang anak.",
  ui_story_31720401_68_dialog_content = "Ini benar-benar menarik.",
  ui_story_31720401_69_dialog_content = "Saya ingin tahu apakah Anda dulu adalah seorang diva seperti sekarang.",
  ui_story_31720401_70_dialog_content = "Hai! Mengapa kita tidak menemukan <color=#FFB400>video itu</color> memperlihatkan PlayerName?",
  ui_story_31720401_71_dialog_content = "<color=#FFB400>Video yang mana</color>?",
  ui_story_31720401_72_dialog_content = "Terima kasih telah mengingatkan saya! Biarkan saya mencoba dan menemukannya!",
  ui_story_31720401_73_dialog_content = "Saya ingat koleksi kaset video saya berantakan. Saya bahkan tidak tahu apa yang ada di beberapa dari mereka ...",
  ui_story_31720401_74_dialog_content = "Anda pergi begitu lama sehingga kami menyortir koleksi untuk Anda.",
  ui_story_31720401_75_dialog_content = "Kami mengambil satu untuk ditonton setiap kali kami merindukanmu. Favorit saya adalah—",
  ui_story_31720401_76_dialog_content = "Mari kita tidak merusaknya. Kita bisa menontonnya bersama sekarang.",
  ui_story_31720401_77_dialog_content = "Oh tidak, aku punya firasat buruk tentang ini...",
  ui_story_31720401_78_dialog_content = "Nah, mungkin Anda bisa mendapatkan inspirasi dari masa lalu Anda!",
  ui_story_31720401_79_dialog_content = "Saya kira jika Anda mengatakannya seperti itu ...",
  ui_story_31720401_80_dialog_content = "<color=#e8d9bb>*Statis*</color>",
  ui_story_31720401_81_dialog_content = "\"Teman-teman tersayang, pemirsa terkasih!\"",
  ui_story_31720401_82_dialog_content = "\"Aku, raja paparazzi Umbraton, baru saja mendarat di gosip yang akan mengejutkan seluruh Astra!\"",
  ui_story_31720401_83_dialog_content = "\"Aktris C-list yang dulu tidak dikenal, Lilica, telah berhasil membuat nama untuk dirinya sendiri ...\"",
  ui_story_31720401_84_dialog_content = "\"sebagai sutradara wanita yang agak terkenal.\"",
  ui_story_31720401_85_dialog_content = "\"Ini tentu mengejutkan, terutama bagi orang dalam industri, termasuk saya sendiri.\"",
  ui_story_31720401_86_dialog_content = "\"Kata-kata di jalan adalah bahwa Lilica pasti mendapatkan dukungan yang kuat, tetapi kita semua bertanya-tanya, siapa itu?\"",
  ui_story_31720401_87_dialog_content = "\"Tanpa basa-basi lagi, izinkan saya memberi tahu Anda semua bahwa pendukung misteri tidak lain adalah ... PlayerName!\"",
  ui_story_31720401_88_dialog_content = "<color=#e8d9bb>*Statis*</color>",
  ui_story_31720401_89_dialog_content = "Tunggu, itu...",
  ui_story_31720401_90_dialog_content = "Ups, memutar klip yang salah. Haha, kalian mengobrol. Biarkan aku terus mencari...",
  ui_story_31720401_91_dialog_content = "B-Benar! Jadi um, PlayerName, biasanya kamu suka makan apa?",
  ui_story_31720401_92_dialog_content = "Hei, aku mengenali suara itu di video! Dia paparazzi yang melecehkanku sebelumnya...",
  ui_story_31720401_93_dialog_content = "Mengapa kita memiliki rekaman videonya?",
  ui_story_31720401_94_dialog_content = "Lilika...",
  ui_story_31720401_95_dialog_content = "Mendesah. Anda pasti terlalu bersemangat.",
  ui_story_31720401_96_dialog_content = "Dia akhirnya membawa PlayerName rumah, dan Anda menunjukkan video yang salah.",
  ui_story_31720401_97_dialog_content = "Apa yang terjadi, Bu?",
  ui_story_31720401_98_dialog_content = "Baik, saya kira jig sudah habis.",
  ui_story_31720401_99_dialog_content = "Jangan khawatir, Lilica, kami membeli ini dari paparazzi.",
  ui_story_31720401_100_dialog_content = "Gosip keji seperti itu tidak akan mengganggu karier Anda lagi.",
  ui_story_31720401_101_dialog_content = "Kamu membelinya? Itu pasti mahal! Kenapa kamu tidak berbicara denganku dulu?",
  ui_story_31720401_102_dialog_content = "Kami tidak melakukannya karena kami tidak ingin masalah ini menjadi gangguan bagi Anda.",
  ui_story_31720401_103_dialog_content = "Tidak heran Anda menelepon PlayerName -ku <color=#FFB400>kekasih yang dikabarkan</color>.",
  ui_story_31720401_104_dialog_content = "Paparazzi itu tidak tahu apa yang dia bicarakan, Bu!",
  ui_story_31720401_105_dialog_content = "Ya, Bu—maksud saya Bu! Saya jamin tidak ada yang seperti itu terjadi di antara kita!",
  ui_story_31720401_106_dialog_content = "Dan gosip tidak membuatku bingung.",
  ui_story_31720401_107_dialog_content = "Saya tidak perlu takut ketika saya tidak memiliki kerangka di lemari saya. Suatu hari mereka semua akan melihat betapa berbakatnya saya!",
  ui_story_31720401_108_dialog_content = "Tentu saja kami percaya padamu, Lilica. Kami hanya takut rumor tak berdasar itu akan menyakitimu...",
  ui_story_31720401_109_dialog_content = "Oh, jangan khawatir tentang itu. Aku tidak akan pernah membiarkan hal-hal seperti itu menyakitiku.",
  ui_story_31720401_110_dialog_content = "Jadi tidak ada lagi menonton sampah seperti itu, oke?",
  ui_story_31720401_111_dialog_content = "Ya, tentu saja, tidak ada lagi hal-hal itu. Lihat yang ini, ini yang sebenarnya favorit kami.",
  ui_story_31720401_112_dialog_content = "<color=#e8d9bb>*Statis*</color>",
  ui_story_31720401_113_dialog_content = "\"Ini ulang tahun labu kita hari ini, tapi kenapa dia terlihat sedih?\"",
  ui_story_31720401_114_dialog_content = "\"Apakah kamu masih bingung dengan rapormu? Jangan biarkan itu membuatmu kecewa, sayang!\"",
  ui_story_31720401_115_dialog_content = "\"Tapi tapi...\"",
  ui_story_31720401_116_dialog_content = "\"Kameranya berputar. Tidakkah kamu ingin memberi tahu kamera keinginan ulang tahunmu?\"",
  ui_story_31720401_117_dialog_content = "\"Sudah merekam?\"",
  ui_story_31720401_118_dialog_content = "\"Ahem... Halo, semuanya!\"",
  ui_story_31720401_119_dialog_content = "\"Aku gadis yang agak suka main-main, agak nakal, agak aneh, tapi sangat cantik, Lilica!\"",
  ui_story_31720401_120_dialog_content = "\"Hari ini adalah hari ulang tahunku, dan aku akan menampilkan tarian bebek untukmu!\"",
  ui_story_31720401_121_dialog_content = "\"Aku bebek kecil, dukun, dukun, dukun!\"",
  ui_story_31720401_122_dialog_content = "\"Saya berlari sangat lambat tetapi untuk berenang saya punya bakat!\"",
  ui_story_31720401_123_dialog_content = "\"Heehee, apakah kamu menyukai tarianku?\"",
  ui_story_31720401_124_dialog_content = "\"Ya, itu sangat lucu!\"",
  ui_story_31720401_125_dialog_content = "\"Ada lagi yang ingin kau katakan, Lilica?\"",
  ui_story_31720401_126_dialog_content = "\"Seperti apa?\"",
  ui_story_31720401_127_dialog_content = "\"Seperti apa yang ingin kamu lakukan ketika kamu dewasa.\"",
  ui_story_31720401_128_dialog_content = "\"Mm... nilaiku tidak bagus, jadi aku tidak bisa menjadi guru...\"",
  ui_story_31720401_129_dialog_content = "\"Tapi aku suka berada di depan kamera!\"",
  ui_story_31720401_130_dialog_content = "\"Tunggu, aku mengerti!\"",
  ui_story_31720401_131_dialog_content = "\"Aku akan membuat film dan menjadi bintang film!\"",
  ui_story_31720401_132_dialog_content = "\"Ibu dan Ayah, aku akan menjadi superstar terhebat dan menghasilkan banyak uang!!\"",
  ui_story_31720401_133_dialog_content = "\"Kalau begitu kamu bisa tinggal di rumah besar dan menonton filmku setiap hari!\"",
  ui_story_31720401_134_dialog_content = "<color=#e8d9bb>*Statis*</color>",
  ui_story_31720401_135_dialog_content = "Hahaha, jadi Lilica bercita-cita menjadi aktris sejak kecil!",
  ui_story_31720401_136_dialog_content = "Anda benar-benar tidak pernah malu kamera.",
  ui_story_31720401_137_dialog_content = "(Tunggu, kenapa tiba-tiba aku merasa suasana menjadi berat?)",
  ui_story_31720401_138_dialog_content = "(... Mengapa mereka semua menyeka air mata?)",
  ui_story_31720401_139_dialog_content = "Maaf…",
  ui_story_31720401_140_dialog_content = "Mengapa kamu meminta maaf, Lilica sayang?",
  ui_story_31720401_141_dialog_content = "Aku... Aku masih belum menjadi superstar.",
  ui_story_31720401_142_dialog_content = "Saya hanya menjadi figuran yang tidak dikreditkan dalam film, dan tidak ada yang saya arahkan yang menjadi populer ...",
  ui_story_31720401_143_dialog_content = "Anak konyol, tahukah Anda mengapa video ini menjadi favorit kami?",
  ui_story_31720401_144_dialog_content = "Karena tarian bebek lucu yang saya lakukan?",
  ui_story_31720401_145_dialog_content = "*tertawa* Tidak. Kami menyukainya karena...",
  ui_story_31720401_146_dialog_content = "Karena kebahagiaan yang menerangi wajah Anda saat Anda mengetahui apa impian Anda.",
  ui_story_31720401_147_dialog_content = "Lampu?",
  ui_story_31720401_148_dialog_content = "Itu benar. Film adalah cahaya hidupku!",
  ui_story_31720401_149_dialog_content = "Anda telah melalui banyak hal untuk mencari nafkah di Umbraton.",
  ui_story_31720401_150_dialog_content = "Saya selalu sangat khawatir. Anda tidak tahu seberapa sering saya berharap Anda baru saja pulang. Tapi kamu tidak pernah menyerah.",
  ui_story_31720401_151_dialog_content = "Anda bekerja keras untuk mendaki dan mencapai posisi Anda hari ini.",
  ui_story_31720401_152_dialog_content = "Kami sangat bangga padamu, Lilica.",
  ui_story_31720401_153_dialog_content = "Ibu, Ayah...",
  ui_story_31720401_154_dialog_content = "Saya pasti akan memenuhi impian masa kecil saya dan membuat Anda lebih bangga!",
  ui_story_31720401_155_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_31720401_156_dialog_content = "Ah! Maaf, saya tidak bermaksud mengganggu momen yang begitu mengharukan!",
  ui_story_31720401_157_dialog_content = "Kurasa aku tidak sengaja menabrak kamera Lilica...",
  ui_story_31720401_158_dialog_content = "Tidak apa-apa, Cellulo memperhatikan kameraku.",
  ui_story_31720401_159_dialog_content = "Lihat, itu masih bekerja dengan sempurna!",
  ui_story_31720401_160_dialog_content = "Tunggu, apakah itu berarti Cellulo telah merekam kita sepanjang waktu?",
  ui_story_31720401_161_dialog_content = "Kasetnya hampir habis...",
  ui_story_31720401_162_dialog_content = "Tidak heran Cellulo terbang mengelilingi semua orang!",
  ui_story_31720401_163_dialog_content = "Apakah kaset itu mahal? Bisakah Anda menggunakannya kembali?",
  ui_story_31720401_164_dialog_content = "!",
  ui_story_31720401_165_dialog_content = "Tidak, jangan menggunakannya kembali.",
  ui_story_31720401_166_dialog_content = "Ini akan bagus untuk film!",
  ui_story_31720401_167_dialog_content = "Hah?",
  ui_story_31720401_168_dialog_content = "Kamu benar, PlayerName, saya benar-benar menemukan inspirasi saya...",
  ui_story_31720401_169_dialog_content = "Film saya berikutnya adalah tentang seorang gadis yang mengejar impian pembuatan filmnya!",
  ui_story_31720401_170_dialog_content = "Semua video rumahan ini dapat menjadi cuplikan dalam film.",
  ui_story_31720401_171_dialog_content = "Kedengarannya menarik. Saya tidak berpikir itu telah dilakukan sebelumnya.",
  ui_story_31720401_172_dialog_content = "Ingatlah untuk menghancurkan video paparazzi ...",
  ui_story_31720401_173_dialog_content = "Mengapa melakukan itu?",
  ui_story_31720401_174_dialog_content = "Mereka adalah bagian dari perjalanan. Saya tidak akan menghapusnya.",
  ui_story_31720401_175_dialog_content = "Juga, saya ingin Anda melanjutkan peran Anda.",
  ui_story_31720401_176_dialog_content = "Saya? Peran apa itu?",
  ui_story_31720401_177_dialog_content = "Itu <color=#FFB400>kekasih yang dikabarkan</color>, tentu saja!",
  ui_story_31720401_178_dialog_content = "Apa?!",
  ui_story_31720601_1_dialog_content = "Ding-ding-dong, ding-ding-dong, ding-dong berbunyi lonceng!",
  ui_story_31720601_2_dialog_content = "Suasana hatimu cukup baik hari ini, Lilica.",
  ui_story_31720601_3_dialog_content = "Heheh, hanya ikut merasakan semangat liburan! Saya ingin sepenuhnya merasakan kegembiraan tahun baru...",
  ui_story_31720601_4_dialog_content = "Ini juga salah satu teknik rahasia saya untuk meningkatkan keterampilan akting saya dalam kehidupan sehari-hari!",
  ui_story_31720601_5_dialog_content = "Ini semua bagian dari latihan diri saya sebagai seorang aktris!",
  ui_story_31720601_6_dialog_content = "Oh, begitu…",
  ui_story_31720601_7_dialog_content = "Selain itu, sebenarnya aku memiliki sesuatu yang benar-benar bisa membuatku bahagia sekarang.",
  ui_story_31720601_8_dialog_content = "Saya baru saja mendapatkan pekerjaan akting baru!",
  ui_story_31720601_9_dialog_content = "Sekarang saya harusnya sudah mampu membeli hadiah untuk orang tua saya tahun ini.",
  ui_story_31720601_10_dialog_content = "Sepertinya kamu harus memberikan hadiah mereka setelah liburan, meskipun begitu.",
  ui_story_31720601_11_dialog_content = "Tidak apa-apa! Tidak ada kata terlambat untuk mengirim seseorang hadiah!",
  ui_story_31720601_12_dialog_content = "Dan orang-orang selalu senang menerimanya, tidak peduli kapan!",
  ui_story_31720601_13_dialog_content = "Bagaimanapun, aku harus menuju ke venue sekarang. Tidak mau terlambat di hari pertamaku!",
  ui_story_31720601_14_dialog_content = "Ngomong-ngomong, di mana tepatnya pertunjukan itu berlangsung?",
  ui_story_31720601_15_dialog_content = "Sebuah panti asuhan terdekat! Heheh, tokoh publik seharusnya melakukan lebih banyak acara amal seperti ini untuk orang lain.",
  ui_story_31720601_16_dialog_content = "Tapi panti asuhan ini memiliki anggaran yang cukup terbatas, mungkin. Mereka bahkan tidak memiliki kostum untukku, jadi aku menggunakan salah satu milikku sendiri!",
  ui_story_31720601_17_dialog_content = "Ingin ikut dan melihat pertunjukanku, PlayerName?",
  ui_story_31720601_18_option_content = "Cerita apa yang diceritakan?",
  ui_story_31720601_19_dialog_content = "Bingung saya! Saya belum diberi naskah.",
  ui_story_31720601_20_option_content = "Lilica... Apakah kamu adalah aktris utama?",
  ui_story_31720601_21_dialog_content = "Saya tidak yakin, karena saya belum membaca naskahnya. Namun, saya setidaknya harus bisa memainkan aktris pendukung utama!",
  ui_story_31720601_22_dialog_content = "Kamu masih belum mendapatkan skripnya? Ini adalah pertunjukan hari libur, jadi seharusnya akan segera terjadi, bukan?",
  ui_story_31720601_23_dialog_content = "Aku tahu, tapi ini permintaan menit terakhir... Lagipula, ini hanya membuktikan bahwa klien memiliki kepercayaan pada keterampilan akting profesional saya!",
  ui_story_31720601_24_dialog_content = "Untuk seorang profesional sejati, seharusnya hanya butuh tiga menit untuk memerankan karakter!",
  ui_story_31720601_25_dialog_content = "Baiklah, cukup bicara. Mari kita pergi sekarang, sehingga kamu bisa melihat keterampilanku dalam bekerja!",
  ui_story_31720601_26_dialog_content = "Ah, jadi mereka memutuskan untuk mengubah gudang ini menjadi belakang panggung sementara.",
  ui_story_31720601_27_dialog_content = "Hmm... Berdiri di belakang panggung seperti ini selalu membantu saya merasa tenang.",
  ui_story_31720601_28_dialog_content = "Ah, akhirnya kamu datang, Nona Lilica! Tolong ganti kostummu secepat mungkin!",
  ui_story_31720601_29_dialog_content = "Tentu! Tapi aku masih belum... Hah? Jadi kamu memang menyiapkan kostum untukku?",
  ui_story_31720601_30_dialog_content = "Ya, dan itu tepat di sana jadi tolong cepat! Astaga, masih banyak yang harus dilakukan.",
  ui_story_31720601_31_dialog_content = "Wow, mereka terlihat sangat sibuk!",
  ui_story_31720601_32_dialog_content = "Tapi inilah suasana yang seharusnya ada di belakang panggung: sibuk, berisik, dan penuh gerakan.",
  ui_story_31720601_33_dialog_content = "Aku akan pergi mengganti pakaianku menjadi kostum!",
  ui_story_31720601_34_dialog_content = "Tunggu, apakah kamu bahkan tahu mana yang milikmu?",
  ui_story_31720601_35_dialog_content = "Nah, hanya ada satu kostum di sana. Jadi itu harus milikku, kan?",
  ui_story_31720601_36_dialog_content = "Nyonya Lilica, kostum Anda adalah yang di sisi ini!",
  ui_story_31720601_37_dialog_content = "Di samping? Tapi itu hanya penyangga pohon, bukan?",
  ui_story_31720601_38_dialog_content = "Ya, tapi seharusnya dipakai seperti kostum. Maaf tidak menjelaskan lebih awal.",
  ui_story_31720601_39_dialog_content = "Dengan kata lain... Saya seharusnya memerankan pohon?",
  ui_story_31720601_40_dialog_content = "Benar. Tolong pakai itu dan menuju ke panggung. Hampir waktunya kamu untuk tampil!",
  ui_story_31720601_41_dialog_content = "Ada skrip di sana jika kamu ingin melihatnya sebentar... Aduh, sibuk sekali...",
  ui_story_31720601_42_dialog_content = "...",
  ui_story_31720601_43_dialog_content = "Tidak heran mereka tidak pernah memberi saya naskah...",
  ui_story_31720601_44_dialog_content = "Ini juga menjelaskan mengapa mereka tidak menyiapkan kostum untukku lebih awal...",
  ui_story_31720601_45_dialog_content = "Lilika...",
  ui_story_31720601_46_dialog_content = "Tapi meskipun berlebihan, seorang aktor profesional harus mengambil setiap peran se-serius mungkin! Jika saya harus memerankan pohon, maka saya akan menjadi pohon terbaik di dunia!",
  ui_story_31720601_47_dialog_content = "Perhatikan saatnya untuk saya bersinar, PlayerName! Saya akan naik ke panggung sekarang!",
  ui_story_31720601_48_dialog_content = "Semoga sukses, Lilica! Aku akan menonton dari sini!",
  ui_story_31720601_49_dialog_content = "<color=#e8d9bb>Beberapa waktu kemudian—</color>",
  ui_story_31720601_50_dialog_content = "<color=#e8d9bb>Dari satu sisi panggung, narator menyajikan cerita sementara aktor utama bermain dengan emosi yang luar biasa.</color>",
  ui_story_31720601_51_dialog_content = "<color=#e8d9bb>Di bagian belakang panggung, Lilica terus menopang kostum pohon beratnya dengan tubuh mungilnya.</color>",
  ui_story_31720601_52_dialog_content = "... Ada orang di pohon itu di belakang sana? Lihat bagaimana ia terus bergoyang bolak-balik! Sungguh konyol!",
  ui_story_31720601_53_dialog_content = "Ini cukup lucu... Aku ingin tahu siapa yang ada di dalamnya?",
  ui_story_31720601_54_dialog_content = "Ceritanya hampir selesai, anak-anak. Pengunjung misterius kita seharusnya akan tiba sebentar lagi, jadi mari kita pelankan suara kita dan tunggu...",
  ui_story_31720601_55_dialog_content = "... Uh? Utusan Tahun Baru belum sampai di sini?",
  ui_story_31720601_56_dialog_content = "Yeah, kenapa si Utusan belum muncul juga? Kenapa kita harus terus menunggu?",
  ui_story_31720601_57_dialog_content = "...",
  ui_story_31720601_58_dialog_content = "... Di mana Utusan Tahun Baru itu?",
  ui_story_31720601_59_dialog_content = "*Mengendus* Apakah kami anak-anak nakal tahun ini? Apakah itulah sebabnya Utusan tidak datang untuk menjumpai kami?",
  ui_story_31720601_60_dialog_content = "<color=#e8d9bb>Saat itu, di belakang panggung.</color>",
  ui_story_31720601_61_dialog_content = "Ini mengerikan! Aktor itu tidak datang lagi!",
  ui_story_31720601_62_dialog_content = "Apa? Maksudmu mereka tidak hanya terlambat?",
  ui_story_31720601_63_dialog_content = "Benar. Oh, apa yang akan kita lakukan...",
  ui_story_31720601_64_dialog_content = "Kami telah mempersiapkan banyak hal untuk drama ini, dan kami telah mencapai akhirnya. Anak-anak masih menunggu...",
  ui_story_31720601_65_dialog_content = "...",
  ui_story_31720601_66_dialog_content = "Saya punya ide...",
  ui_story_31720601_67_dialog_content = "Semua terserah padamu sekarang, Lilica.",
  ui_story_31720601_68_dialog_content = "Hah? Apakah ini benar-benar baik-baik saja?",
  ui_story_31720601_69_dialog_content = "... Itu adalah, selama keterampilan aktingmu mampu melakukan tugasnya...",
  ui_story_31720601_70_dialog_content = "Dia bagus! Kamu bisa mengandalkan dia!",
  ui_story_31720601_71_dialog_content = "PlayerName…",
  ui_story_31720601_72_dialog_content = "Berimprovisasi hanyalah bagian lain dari akting, bukan? Dan drama ini sekarang lebih dari sebelumnya membutuhkan seorang pahlawan wanita!",
  ui_story_31720601_73_dialog_content = "... Aku mengerti! Tunggu saja penampilanku!",
  ui_story_31720601_74_dialog_content = "Dan sekarang... Mari kita sambut Utusan Tahun Baru ke atas panggung!",
  ui_story_31720601_75_dialog_content = "...",
  ui_story_31720601_76_dialog_content = "Ho ho ho ho ho!",
  ui_story_31720601_77_dialog_content = "Hei, tawa itu...",
  ui_story_31720601_78_dialog_content = "Maaf atas keterlambatan, anak-anak! Hadiah-hadiahmu sangat berat sehingga membutuhkan waktu lebih lama untuk mengangkutnya ke sini!",
  ui_story_31720601_79_dialog_content = "Ho ho? Tapi kenapa wajah murung, anak-anak? Saya tidak ingat membawa hadiah untuk anak-anak yang menangis!",
  ui_story_31720601_80_dialog_content = "A-Aku tidak menangis!",
  ui_story_31720601_81_dialog_content = "Aku juga! Ini adalah... Ini air liur! Aku ngiler karena aku lapar. Itu saja!",
  ui_story_31720601_82_dialog_content = "Ho ho ho ho! Maafkan saya nona, tapi bisakah kamu membantu saya membawa keluar hadiah-hadiah mereka?",
  ui_story_31720601_83_dialog_content = "S... Tentu! Baiklah anak-anak, kita akan membantu Utusan dengan hadiah-hadiahmu, jadi jadilah baik dan tunggu di sini.",
  ui_story_31720601_84_dialog_content = "Nah, anak-anak, dengan kekuatan sihir bahagia ku—",
  ui_story_31720601_85_dialog_content = "Saya akan mengusir semua nasib buruk di dunia sehingga semua orang dapat menikmati kehidupan yang bahagia!",
  ui_story_31720601_86_dialog_content = "Tapi untuk melakukan itu, aku butuh bantuanmu. Sihir hanya bekerja ketika anak-anak yang bahagia bernyanyi bersamaku. Apakah kamu siap?",
  ui_story_31720601_87_dialog_content = "Ya!",
  ui_story_31720601_88_dialog_content = "<color=#e8d9bb>Sebuah paduan suara hangat dan bahagia terdengar dari dalam panti asuhan, membuat malam musim dingin di Umbraton sedikit kurang dingin.</color>",
  ui_story_31720601_89_dialog_content = "Fiuh! Saya akan menyebut penampilan malam ini sukses!",
  ui_story_31720601_90_option_content = "Semua ini berkat dirimu!",
  ui_story_31720601_91_option_content = "Cara melompat ke dalam peran seperti itu!",
  ui_story_31720601_92_dialog_content = "Heehee, bukan apa-apa!",
  ui_story_31720601_93_dialog_content = "Oh, dan wanita dari panti asuhan memberiku beberapa kue sebagai hadiah. Ada juga untukmu!",
  ui_story_31720601_94_dialog_content = "Demi aku?",
  ui_story_31720601_95_dialog_content = "Betul sekali! Jika bukan karena kepercayaan dan doronganmu, saya tidak akan bisa melakukan pertunjukan hari ini.",
  ui_story_31720601_96_dialog_content = "Yang berarti kamu juga memainkan peran penting hari ini!",
  ui_story_31720601_97_dialog_content = "Ini dia!",
  ui_story_31720601_98_dialog_content = "Baiklah…",
  ui_story_31720601_99_dialog_content = "Ayolah, kamu tidak akan menolak undangan dari seorang aktris sukses, kan?",
  ui_story_31720601_100_dialog_content = "Yah, kalau kamu bersikeras.",
  ui_story_31720601_101_dialog_content = "Heehee, begitu dong!"
}
return config
